------------------------------------------------------------
----- ROOT ID FUNCTION FOR: [Event].[series_id]
------------------------------------------------------------
IF OBJECT_ID('[eventbrite].[fnEventseries_id_GetRootID]', 'IF') IS NOT NULL
    DROP FUNCTION [eventbrite].[fnEventseries_id_GetRootID];
GO

CREATE FUNCTION [eventbrite].[fnEventseries_id_GetRootID]
(
    @RecordID nvarchar(255),
    @ParentID nvarchar(255)
)
RETURNS TABLE
AS
RETURN
(
    WITH CTE_RootParent AS (
        SELECT
            [id],
            [series_id],
            [id] AS [RootParentID],
            0 AS [Depth]
        FROM
            [eventbrite].[Event]
        WHERE
            [id] = COALESCE(@ParentID, @RecordID)

        UNION ALL

        SELECT
            c.[id],
            c.[series_id],
            c.[id] AS [RootParentID],
            p.[Depth] + 1 AS [Depth]
        FROM
            [eventbrite].[Event] c
        INNER JOIN
            CTE_RootParent p ON c.[id] = p.[series_id]
        WHERE
            p.[Depth] < 100
    )
    SELECT TOP 1
        [RootParentID] AS RootID
    FROM
        CTE_RootParent
    WHERE
        [series_id] IS NULL
    ORDER BY
        [RootParentID]
);
GO

